/**
 * Tooltip HTML for fetiche panel berry chips and feed buttons.
 */

import { escapeHtml, formatNumber, formatNumberHeader } from '../../formatters.ts';
import {
    formatFeticheBerryStatHintHtml,
    hasFeticheBerryStatHint,
    type FeticheBerryStatEffect,
} from '../../constants/balance/feticheBerries.ts';
import type { FeticheBerryFeedSnapshot, FeticheSnapshot, FeticheStatBlock } from './feticheSnapshot.ts';
import type { FeticheTaste } from './feticheLogic.ts';

export type FeticheBerryTooltipUi = {
    tasteLoved: string;
    tasteLiked: string;
    tasteNeutral: string;
    tasteDisliked: string;
    tasteHated: string;
    tasteCombatHint?: string;
};

const TASTE_ICON: Record<FeticheTaste, string> = {
    loved: '♥♥',
    liked: '♥',
    neutral: '–',
    disliked: '✕',
    hated: '✕✕',
};

export function feticheTasteLabel(taste: FeticheTaste, ui: FeticheBerryTooltipUi): string {
    const labels: Record<FeticheTaste, string> = {
        loved: ui.tasteLoved,
        liked: ui.tasteLiked,
        neutral: ui.tasteNeutral,
        disliked: ui.tasteDisliked,
        hated: ui.tasteHated,
    };
    return labels[taste];
}

export type FeticheBerryTooltipOpts = {
    showQty?: boolean;
};

function appendStatHintLine(parts: string[], statEffect: FeticheBerryStatEffect | null | undefined): void {
    if (!hasFeticheBerryStatHint(statEffect)) return;
    parts.push(formatFeticheBerryStatHintHtml(statEffect!));
}

export function buildFeticheBerryTooltipContent(
    berry: Pick<
        FeticheBerryFeedSnapshot,
        'name' | 'taste' | 'tasteIcon' | 'description' | 'qty' | 'statEffect'
    >,
    ui: FeticheBerryTooltipUi,
    opts?: FeticheBerryTooltipOpts,
): { title: string; body: string } {
    const tasteLabel = feticheTasteLabel(berry.taste, ui);
    const parts: string[] = [
        `${escapeHtml(berry.tasteIcon)} ${escapeHtml(tasteLabel)}`,
    ];
    appendStatHintLine(parts, berry.statEffect);
    if (berry.description) {
        parts.push(escapeHtml(berry.description));
    }
    if (opts?.showQty) {
        parts.push(`×${Math.max(0, Math.floor(Number(berry.qty) || 0))}`);
    }
    return {
        title: escapeHtml(berry.name),
        body: parts.join('<br>'),
    };
}

export type BerryTreeBerryTooltipEntry = {
    name: string;
    feticheTaste: string | null;
    feticheStatEffect: FeticheBerryStatEffect | null;
    description?: string | null;
};

export function buildBerryTreeBerryTooltipContent(
    entry: BerryTreeBerryTooltipEntry,
    ui: FeticheBerryTooltipUi,
): { title: string; body: string } | null {
    if (!entry.feticheTaste) return null;
    const taste = entry.feticheTaste as FeticheTaste;
    const tasteLabel = feticheTasteLabel(taste, ui);
    const parts: string[] = [
        `${escapeHtml(TASTE_ICON[taste])} ${escapeHtml(tasteLabel)}`,
    ];
    if (ui.tasteCombatHint) parts.push(escapeHtml(ui.tasteCombatHint));
    appendStatHintLine(parts, entry.feticheStatEffect);
    if (entry.description) {
        parts.push(escapeHtml(entry.description));
    }
    return {
        title: escapeHtml(entry.name),
        body: parts.join('<br>'),
    };
}

export function buildFeticheStatTooltipContent(
    snap: Pick<
        FeticheSnapshot,
        | 'displaySpeciesName'
        | 'speciesName'
        | 'spriteUrl'
        | 'level'
        | 'isMaxLevel'
        | 'stats'
        | 'baseStatsAtLevel'
        | 'berryBonusStats'
        | 'speciesRawBaseStats'
        | 'speciesStatMultipliers'
        | 'gainsPerSec'
        | 'statsAtNextLevel'
        | 'gainsAtNextLevel'
        | 'gainsTotalPerSec'
        | 'transmissionSec'
    >,
    key: keyof FeticheStatBlock,
    statLabel: string,
    lang: 'fr' | 'en' = 'fr',
): { title: string; body: string } {
    const isEn = lang === 'en';
    const pokeName = snap.displaySpeciesName || snap.speciesName || 'Fétiche';
    const totalStat = snap.stats[key] ?? 0;
    const levelStat = snap.baseStatsAtLevel?.[key] ?? totalStat;
    const berryBonus = snap.berryBonusStats?.[key] ?? 0;
    const rawSpeciesBase = snap.speciesRawBaseStats?.[key] ?? 0;
    const rawSpeciesStr = `${Math.round(rawSpeciesBase)}`;
    const mult = snap.speciesStatMultipliers?.[key] ?? 1;
    const multStr = mult.toFixed(2).replace(/\.?0+$/, '');
    const multBonusPct = Math.round((mult - 1) * 100);
    const gainPerSec = snap.gainsPerSec[key] ?? 0;
    const nextStat = snap.statsAtNextLevel?.[key] ?? null;
    const nextGain = snap.gainsAtNextLevel?.[key] ?? null;
    const sharePct = snap.gainsTotalPerSec > 0 && gainPerSec > 0
        ? Math.round((gainPerSec / snap.gainsTotalPerSec) * 100)
        : 0;

    const spriteHtml = snap.spriteUrl
        ? `<img class="header-stat-tooltip-fetiche-sprite" src="${escapeHtml(snap.spriteUrl)}" alt="" loading="lazy" />`
        : '';

    const sec1Title = isEn ? 'Fétiche Stat' : 'Stat du Fétiche';
    const levelRowLabel = isEn
        ? `Level Stat (Lv. ${snap.level})`
        : `Stat de niveau (Niv. ${snap.level})`;
    const berryRowLabel = isEn ? 'Berry bonuses (fed)' : 'Bonus des baies (nourri)';
    const nextLevelStatLabel = isEn
        ? `At Lv. ${snap.level + 1}`
        : `Au Niv. ${snap.level + 1}`;

    const sec2Title = isEn ? 'Species Identity' : 'Identité d\'espèce';
    const baseStatRowLabel = isEn
        ? `Base stat (${pokeName})`
        : `Stat de base (${pokeName})`;
    const multRowLabel = isEn ? 'Specialty multiplier' : 'Multiplicateur d\'espèce';

    const sec3Title = isEn ? 'Production Breakdown' : 'Décomposition de la production';
    const formulaStatLabel = isEn ? 'Fétiche Stat' : 'Stat du Fétiche';
    const formulaMultLabel = isEn ? '× Species multiplier' : '× Multiplicateur d\'espèce';
    const formulaTimeLabel = isEn ? '× Presence time' : '× Temps de présence';
    const shareRowLabel = isEn ? 'Share of total Fétiche gain' : 'Part de la production totale';

    const statRows: string[] = [
        `<div class="header-stat-tooltip-row">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(levelRowLabel)}</span>` +
        `<span class="header-stat-tooltip-val">${escapeHtml(formatNumber(levelStat))}</span>` +
        `</div>`,
        `<div class="header-stat-tooltip-row">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(berryRowLabel)}</span>` +
        `<span class="header-stat-tooltip-val ${berryBonus > 0 ? 'header-stat-tooltip-val--pos' : ''}">+${escapeHtml(formatNumber(berryBonus))}</span>` +
        `</div>`,
    ];

    if (!snap.isMaxLevel && nextStat != null && nextStat > totalStat) {
        statRows.push(
            `<div class="header-stat-tooltip-subrow">` +
            `<span class="header-stat-tooltip-label">↳ ${escapeHtml(nextLevelStatLabel)}</span>` +
            `<span class="header-stat-tooltip-val header-stat-tooltip-val--sub">→ ${escapeHtml(formatNumber(nextStat))}</span>` +
            `</div>`,
        );
    }

    const identityRows: string[] = [
        `<div class="header-stat-tooltip-row">` +
        `<span class="header-stat-tooltip-label">${spriteHtml}${escapeHtml(baseStatRowLabel)}</span>` +
        `<span class="header-stat-tooltip-val">${escapeHtml(rawSpeciesStr)}</span>` +
        `</div>`,
        `<div class="header-stat-tooltip-row">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(multRowLabel)}</span>` +
        `<span class="header-stat-tooltip-val header-stat-tooltip-val--boost">×${escapeHtml(multStr)} (+${multBonusPct}%)</span>` +
        `</div>`,
    ];

    const prodRows: string[] = [
        `<div class="header-stat-tooltip-row">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(formulaStatLabel)}</span>` +
        `<span class="header-stat-tooltip-val">${escapeHtml(formatNumber(totalStat))}</span>` +
        `</div>`,
        `<div class="header-stat-tooltip-subrow">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(formulaMultLabel)}</span>` +
        `<span class="header-stat-tooltip-val header-stat-tooltip-val--boost">×${escapeHtml(multStr)}</span>` +
        `</div>`,
        `<div class="header-stat-tooltip-subrow">` +
        `<span class="header-stat-tooltip-label">${escapeHtml(formulaTimeLabel)}</span>` +
        `<span class="header-stat-tooltip-val header-stat-tooltip-val--sub">×${escapeHtml(formatNumberHeader(snap.transmissionSec))}s</span>` +
        `</div>`,
    ];

    if (!snap.isMaxLevel && nextGain != null && nextGain > gainPerSec) {
        prodRows.push(
            `<div class="header-stat-tooltip-subrow">` +
            `<span class="header-stat-tooltip-label">↳ ${escapeHtml(nextLevelStatLabel)}</span>` +
            `<span class="header-stat-tooltip-val header-stat-tooltip-val--gain">→ +${escapeHtml(formatNumberHeader(nextGain))}/s</span>` +
            `</div>`,
        );
    }

    if (sharePct > 0) {
        prodRows.push(
            `<div class="header-stat-tooltip-row">` +
            `<span class="header-stat-tooltip-label">${escapeHtml(shareRowLabel)}</span>` +
            `<span class="header-stat-tooltip-val">${sharePct}%</span>` +
            `</div>`,
        );
    }

    const body =
        `<div class="header-stat-tooltip">` +
        `<div class="header-stat-tooltip-section">` +
        `<div class="header-stat-tooltip-heading">` +
        `<span>${escapeHtml(sec1Title)}</span>` +
        `<span class="header-stat-tooltip-total">${escapeHtml(formatNumber(totalStat))}</span>` +
        `</div>` +
        `${statRows.join('')}` +
        `</div>` +
        `<div class="header-stat-tooltip-section">` +
        `<div class="header-stat-tooltip-heading">` +
        `<span>${escapeHtml(sec2Title)}</span>` +
        `<span class="header-stat-tooltip-total header-stat-tooltip-val--boost">×${escapeHtml(multStr)}</span>` +
        `</div>` +
        `${identityRows.join('')}` +
        `</div>` +
        `<div class="header-stat-tooltip-section">` +
        `<div class="header-stat-tooltip-heading">` +
        `<span>${escapeHtml(sec3Title)}</span>` +
        `<span class="header-stat-tooltip-total header-stat-tooltip-val--gain">+${escapeHtml(formatNumberHeader(gainPerSec))}/s</span>` +
        `</div>` +
        `${prodRows.join('')}` +
        `</div>` +
        `</div>`;

    return {
        title: `${escapeHtml(pokeName)} — ${escapeHtml(statLabel)}`,
        body,
    };
}
